cd ../analysis && python3 - <<'EOF'
import csv, collections
rows=list(csv.DictReader(open('data/processed/clean_scheduled_domestic.csv')))
def shares(month, key):
    tot=collections.Counter()
    for r in rows:
        if r['date'][:7]==month: tot[r[key]]+=float(r['passengers'])
    T=sum(tot.values()); return {k:100*v/T for k,v in tot.items()}
for m in ['2021-12','2022-01']:
    b=shares(m,'airline'); o=shares(m,'ownership_group')
    print(m,'brandHHI',round(sum(v*v for v in b.values())),'ownHHI',round(sum(v*v for v in o.values())))
b=shares('2021-12','airline')
tata=['Air India','Air India Express','Vistara','AirAsia India']
s=[b.get(x,0) for x in tata]; print({x:round(b.get(x,0),2) for x in tata})
mech=sum(2*s[i]*s[j] for i in range(4) for j in range(i+1,4)); print('mech all 4',round(mech))
mech2=mech-2*s[0]*s[1]; print('mech excl AI-AIX (already grouped)',round(mech2))
# exit decomposition contributions for Go First
import itertools
d=list(csv.DictReader(open('data/processed/exit_share_decomposition.csv')))
for ev in ['Jet Airways exit','Go First exit']:
    tot=0
    for r in d:
        if r['event']==ev and r['measure']=='passengers_share':
            pre=float(r['pre_share']); ch=float(r['change_pp'])
            c=2*pre*ch+ch*ch; tot+=c
            if abs(c)>20: print(ev,r['group'],round(c))
    print(ev,'sum of contributions',round(tot))
EOF
