edits.text:
A.\ Exits}

\textit{Stage 1: Market shares.}
\[
s_{gt} = \frac{Q_{gt}}{\sum_j Q_{jt}} \times 100, \qquad \bar s_g^{\,k} = \frac{1}{|W^{k}|}\sum_{t \in W^{k}} s_{gt}
\]
$s_{gt}$ is the share of ownership group $g$ in month $t$, with $Q$ as passengers or seat-km. $\bar s_g^{\,k}$ is its mean over a window of up to 12 months before ($k=\text{pre}$) or after ($k=\text{post}$) an exit, excluding the exit month.

\textit{Stage 2: Who absorbed the exiting share.}
\[
\Delta s_g = \bar s_g^{\,\text{post}} - \bar s_g^{\,\text{pre}}, \qquad a_g = \frac{\Delta s_g}{\bar s_x^{\,\text{pre}}} \times 100
\]
$\Delta s_g$ is the change in share. $a_g$ is the portion of the exiting airline $x$'s share taken by $g$ (all $a_g$ sum to 100\%). A higher $a_g$ for seat-km than for passengers marks capacity-led growth, checked against company filings \parencite{spicejet2020annual,goair2021drhp}.

\textit{Stage 3: Who drove concentration.}
\[
c_g = 2\,\bar s_g^{\,\text{pre}}\,\Delta s_g + (\Delta s_g)^2, \qquad \Delta\text{HHI} = -\big(\bar s_x^{\,\text{pre}}\big)^2 + \sum_{g \neq x} c_g
\]
$c_g$ is group $g$'s contribution to the change in \HHI{}. $\Delta\text{HHI}$ is the total change after the exit.

\textbf{B.\ Consolidation}

\textit{Stage 1: Effect of common ownership.}
\[
\Delta\text{HHI}^{\text{mech}} = 2\sum_{a<b;\; a,b \in G} s_a\, s_b, \qquad R = \Delta\text{HHI}^{\text{obs}} - \Delta\text{HHI}^{\text{mech}}
\]
$\Delta\text{HHI}^{\text{mech}}$ is the rise in \HHI{} from common ownership alone, for brands $G$ at shares in the month before the event. $R$ is the remaining change beyond it, using ownership \HHI{} at the January 2022 acquisition and brand \HHI{} at the December 2024 mergers.

\textit{Stage 2: Testing CCI's assumption.}
\[
F_t = 100 - \CRtwo{}_t, \qquad \Delta F = \bar F^{\,\text{post}} - \bar F^{\,\text{pre}}
\]
$F_t$ is the fringe share outside the two largest groups. $\Delta F$ is the change in its mean from FY2022--23 to after CCI's approval in September 2023. A fall means the low-cost competition CCI relied on weakened

