mine{\textbf{Confounding trends (O2):} Akasa Air's ramp-up, SpiceJet's decline and the exiting airlines' own decline before exit overlap the windows, so not all of each change is caused by the exit. Addressed with 6-month windows and a Jet pre-window ending in December 2018.}
    \item \mine{\textbf{Small sample (O2):} two exits and two consolidation steps allow no significance tests. The decomposition is an exact accounting identity, and results are checked on both passengers and seat-km.}
    \item \mine{\textbf{Reverse causality (O2):} rivals' growth may have helped cause the exits, so gains are described as redistribution, not as effects of the exit.}
    \item \mine{\textbf{Different market definitions (O2):} CCI judged the merger on city pairs and we measure the national market, so our results complement CCI's decision rather than test it.}

[\mine{\textbf{H5a.}}] \mine{(O2) \textbf{Exit absorption:} We expect IndiGo's absorption ratio to be the largest of any group after both exits, and larger after Go First than after Jet Airways.}
    \item[\mine{\textbf{H5b.}}] \mine{(O2) \textbf{Exit-driven concentration:} We expect IndiGo's gain to account for more than half of the rise in \HHI{} after each exit.}
    \item[\mine{\textbf{H5c.}}] \mine{(O2) \textbf{Tata consolidation:} We expect the observed rise in \HHI{} at each Tata step to be at least the mechanical rise from common ownership alone.}
    \setcounter{enumi}{5}

Who gained from exits and consolidation}
\begin{mypart}
\textbf{A.\ Exits}

\textit{Stage 1: Market shares.}
\[
s_{gt} = \frac{Q_{gt}}{\sum_j Q_{jt}} \times 100, \qquad \bar s_g^{\,k} = \frac{1}{|W^{k}|}\sum_{t \in W^{k}} s_{gt}
\]
$s_{gt}$ is the share of ownership group $g$ in month $t$, with $Q$ as passengers or seat-km. $\bar s_g^{\,k}$ is its mean over a window of up to 12 months before ($k=\text{pre}$) or after ($k=\text{post}$) an exit, excluding the exit month.

\textit{Stage 2: Who absorbed the exiting share.}
\[
\Delta s_g = \bar s_g^{\,\text{post}} - \bar s_g^{\,\text{pre}}, \qquad a_g = \frac{\Delta s_g}{\bar s_x^{\,\text{pre}}} \times 100
\]
$\Delta s_g$ is the change in share. $a_g$ is the portion of the exiting airline $x$'s share taken by $g$ (all $a_g$ sum to 100\%). Where a group's seat-km ratio exceeds its passenger ratio, indicating capacity-led growth, we check its company filings for slot and aircraft additions \parencite{spicejet2020annual,goair2021drhp}.

\textit{Stage 3: Who drove concentration.}
\[
c_g = 2\,\bar s_g^{\,\text{pre}}\,\Delta s_g + (\Delta s_g)^2, \qquad \Delta\text{HHI} = -\big(\bar s_x^{\,\text{pre}}\big)^2 + \sum_{g \neq x} c_g
\]
$c_g$ is group $g$'s contribution to the change in \HHI{}. $\Delta\text{HHI}$ is the total change after the exit. Comparing each $c_g$ with $\Delta\text{HHI}$ shows which group's gain raised concentration the most after an exit.

\textbf{B.\ Consolidation}

\textit{Stage 1: Effect of common ownership.}
\[
\Delta\text{HHI}^{\text{mech}} = 2\sum_{a<b;\; a,b \in G} s_a\, s_b
\]
$\Delta\text{HHI}^{\text{mech}}$ is the rise in \HHI{} from common ownership alone, for brands $G$ at shares in the month before the event. It is compared with the observed change in ownership \HHI{} at the January 2022 acquisition and in brand \HHI{} at the December 2024 mergers, and the result is discussed against the reasoning in CCI's combination order \parencite{cci2023vistara}.

\textbf{Justification.} Two exits and two consolidation steps are too few for a regression. A before-and-after decomposition shows directly where the share went, the filings explain why, and the CCI order grounds the policy discussion in the regulator's actual reasoning.
\end{mypar

mine{\noindent\textbf{O2: Unit of Analysis.}}

\mine{The main unit of analysis is the \textbf{market-month}: the Indian scheduled domestic passenger market in a given month, for which concentration measures are computed. These are built from a supporting unit, the \textbf{airline-month}, which records each airline's passengers and seat capacity. Airlines are aggregated into \textbf{ownership groups} for the ownership-adjusted measures.}

\mine{All four objectives use the same airline-month data, arranged differently (Table~\ref{tab:units}).}

\begingroup
\small
\captionof{table}{Unit used by each objective}
\label{tab:units}
\noindent\begin{tabularx}{\textwidth}{|>{\raggedright\arraybackslash}p{0.08\textwidth}|>{\raggedright\arraybackslash}X|}
\hline
\textbf{Obj.} & \textbf{Unit} \\
\hline
O1 & Market-month \\
\hline
\mine{O2} & \mine{Ownership group before vs.\ after each exit; market-month before vs.\ after each Tata consolidation step} \\
\hline
O3 & Each entrant airline over its lifetime \\
\hline
O4 & Market-month (route-month if city-pair data is found) \\
\hline
\end{tabularx}
\endgroup

\begin{mypart}
\begin{itemize}[leftmargin=2em]
    \item \textbf{Time period:} January 2015 to July 2026, monthly (138 market-months; April 2020 has no scheduled passenger traffic).
    \item \textbf{Geography:} all of India, at national level.
    \item \textbf{Market:} scheduled domestic passenger services only; international, charter and cargo-only operations are excluded.
\end{itemize}
\end{mypart}

