\subsection{Testable hypotheses}
\begin{draft}
\begin{enumerate}[leftmargin=2.6em,label=\textbf{H\arabic*.},ref=H\arabic*]
    \item (\objref{1}) \textbf{Lasting steps:} We expect each of the four consolidation events to be associated with a positive and lasting step in ownership HHI ($\gamma_k>0$ and statistically significant).\label{hyp:lasting-steps}
    \item (\objref{1}, \objref{4}) \textbf{Ownership effects:} Comparing January 2015--December 2021 with January 2022--July 2026, we expect the average gap between ownership HHI and brand HHI to increase, while the average gap between MHHI and ownership HHI decreases. Over the full study period, we expect the average partial-ownership adjustment to be smaller than the average grouping effect.\label{hyp:ownership-effects}
    \item (\objref{2}) \textbf{Exit absorption:} We expect IndiGo's absorption ratio to be the largest of any group after both exits, and larger after Go First than after Jet Airways.\label{hyp:exit-absorption}
    \item (\objref{2}) \textbf{Exit-driven concentration:} We expect IndiGo's gain to account for more than half of the rise in \HHI{} after each exit.\label{hyp:exit-concentration}
    \item (\objref{4}) \textbf{National concentration:} We expect IndiGo and the Air India Group to remain the two largest groups in every month from December 2024 to July 2026, with CR2 $\geq$80\% and a share gap above 20 percentage points. HHI $>$1,800 is not tested separately, since CR2 $\geq$80\% already implies HHI $\geq$3,200.\label{hyp:national-concentration}
    \item (\objref{4}) \textbf{Route concentration:} We expect ownership-adjusted scheduled-flight-frequency HHI to exceed 1,800 in more than half of the available route-month observations for the selected 20 airport pairs.\label{hyp:route-concentration}
    \item (\objref{4}) \textbf{Capacity buffer:} We expect rivals' unused capacity relative to IndiGo's passenger-kilometres to be lower in December 2025 than in December 2024.\label{hyp:capacity-buffer}
\end{enumerate}
\end{draft}

