python3 - <<'EOF'
import csv
from collections import defaultdict
rows=list(csv.DictReader(open('data/processed/exit_share_decomposition.csv')))
for ev in ['Jet Airways exit','Go First exit']:
  for meas in ['passengers_share','seat_km_share']:
    rs=[r for r in rows if r['event']==ev and r['measure']==meas]
    x=[r for r in rs if float(r['post_share'])==0 and float(r['pre_share'])>5][0]
    sx=float(x['pre_share']); tot=0; out=[]
    for r in rs:
      if r is x: continue
      pre=float(r['pre_share']); d=float(r['change_pp']); c=2*pre*d+d*d; tot+=c
      if abs(d)>=0.5: out.append((r['group'],round(pre,2),round(d,2),r['pct_of_exiting_share'],round(c,1)))
